draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  for (let i = 0; i < 20; i++) {
    ctx.beginPath();
    let x = Math.cos(i + t) * W / 2 + W / 2;
    let y = Math.sin(i + t * 1.3) * H / 2 + H / 2;
    ctx.arc(x, y, 2 + Math.sin(t + i) * 2, 0, 2 * Math.PI);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2);
  ctx.lineTo(W / 2 + Math.cos(t) * W / 4, H / 2 + Math.sin(t) * H / 4);
  ctx.stroke();
  ctx.restore();
}
